% Include libraries if needed
include "globals.mzn";

% Input data
int: n = 20; % Total number of steps
set of int: possible_steps = {3, 4, 5}; % Possible steps at a time

% Decision Variables
array[1..n] of var 0..5: steps; % Steps taken at each move, 0 if no steps are taken

% Constraints
% Ensure the sum of steps equals n
constraint sum(steps) = n;

% Ensure each step is either 0 or one of the possible steps
constraint forall(i in 1..n)(steps[i] in possible_steps union {0});

% Ensure that once we reach the top, no more steps are taken
constraint exists(i in 1..n)(sum(j in 1..i)(steps[j]) = n /\ forall(j in i+1..n)(steps[j] = 0));

solve satisfy;

output [
    "{",
    "\"" ++ "steps" ++ "\": [" ++ join(",", [show(steps[i]) | i in 1..n]) ++ "]",
    "}"
];
```

