% Input data
int: num_children = 5;
set of int: Children = 1..num_children;
set of int: Ages = {3, 5, 7, 8, 10};
set of int: Countries = 1..num_children;
set of int: Stories = 1..num_children;

% Mapping of children to names for output
array[Children] of string: child_names = ["Bernice", "Carl", "Debby", "Sammy", "Ted"];
array[Countries] of string: country_names = ["Ethiopia", "Kazakhstan", "Lithuania", "Morocco", "Yemen"];
array[Stories] of string: story_names = ["burning bush", "captivity", "Moses’s youth", "Passover", "the Ten Commandments"];

% Decision Variables
array[Children] of var Ages: age;
array[Children] of var Countries: country;
array[Children] of var Stories: story;

% Constraints
% 1. Debby’s family is from Lithuania.
constraint country[3] = 3;

% 2. The child who told the story of the Passover is two years older than Bernice.
constraint age[story = 4] = age[1] + 2;

% 3. The child whose family is from Yemen is younger than the child from the Ethiopian family.
constraint age[country = 5] < age[country = 1];

% 4. The child from the Moroccan family is three years older than Ted.
constraint age[country = 4] = age[5] + 3;

% 5. Sammy is three years older than the child who told the story of Moses’s youth in the house of the Pharaoh.
constraint age[4] = age[story = 3] + 3;

% All ages, countries, and stories must be different
constraint all_different(age);
constraint all_different(country);
constraint all_different(story);

% Solve the model
solve satisfy;

% Print the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "ages" ++ "\": [" ++ join(",", [show(age[c]) | c in Children]) ++ "]",
        "\"" ++ "children" ++ "\": [" ++ join(",", [show(c) | c in Children]) ++ "]",
        "\"" ++ "countries" ++ "\": [" ++ join(",", [show(country[c]) | c in Children]) ++ "]",
        "\"" ++ "stories" ++ "\": [" ++ join(",", [show(story[c]) | c in Children]) ++ "]"
    ]),
    "}"
];
