% Include libraries if needed
include "globals.mzn";

% Input data
int: num_cows = 25;
int: num_sons = 5;
array[1..num_sons] of int: cows_per_son = [7, 6, 5, 4, 3];
array[1..num_cows] of int: milk_per_cow = [i | i in 1..num_cows];

% Decision Variables
array[1..num_cows] of var 0..num_sons-1: cow_assignments; % 0 to 4 representing the sons
array[1..num_sons] of var int: total_milk_per_son;

% Constraints
% Each cow is assigned to exactly one son
constraint forall(c in 1..num_cows) (
    cow_assignments[c] >= 0 /\ cow_assignments[c] < num_sons
);

% Each son gets the correct number of cows
constraint forall(s in 1..num_sons) (
    sum(c in 1..num_cows) (bool2int(cow_assignments[c] = s-1)) = cows_per_son[s]
);

% Calculate total milk per son
constraint forall(s in 1..num_sons) (
    total_milk_per_son[s] = sum(c in 1..num_cows) (bool2int(cow_assignments[c] = s-1) * milk_per_cow[c])
);

% All sons should produce the same amount of milk
constraint forall(s1, s2 in 1..num_sons where s1 < s2) (
    total_milk_per_son[s1] = total_milk_per_son[s2]
);

solve satisfy;

output [
    "{",
    "\"" ++ "cow_assignments" ++ "\": [" ++ join(",", [show(cow_assignments[c]) | c in 1..num_cows]) ++ "]",
    "}"
];
```

