% Include libraries if needed
include "globals.mzn";

% Input data
int: num_people = 8;
set of int: People = 1..num_people;
array[People] of set of People: compatible = [
    {2, 3},
    {1, 6},
    {1, 4, 7},
    {2},
    {2},
    {5},
    {8},
    {3}
];

% Decision Variables
array[People, People] of var 0..1: transplants;

% Constraints
% Each person can donate to at most one person
constraint forall(i in People) (
    sum(j in People) (transplants[i, j]) <= 1
);

% Each person can receive from at most one person
constraint forall(j in People) (
    sum(i in People) (transplants[i, j]) <= 1
);

% If person i donates to person j, then j must be in the compatible list of i
constraint forall(i in People, j in People) (
    transplants[i, j] = 1 -> j in compatible[i]
);

% Objective: Maximize the number of transplants
var int: total_transplants = sum(i in People, j in People) (transplants[i, j]);

solve maximize total_transplants;

% Print the solution in JSON format
output [
    "{",
    "\"transplants\": [" ++ join(",", [ "[" ++ join(",", [show(transplants[i, j]) | j in People]) ++ "]" | i in People]) ++ "]",
    "}"
];
```

