% Input data
int: n = 4;
int: magic_sum = n * (n^2 + 1) div 2;

% Decision Variables
array[1..n, 1..n] of var 1..n^2: square;

% Constraints
% All numbers from 1 to n^2 must be used exactly once
constraint all_different([square[i, j] | i in 1..n, j in 1..n]);

% Sum of each row must be equal to magic_sum
constraint forall(i in 1..n) (
    sum(j in 1..n) (square[i, j]) = magic_sum
);

% Sum of each column must be equal to magic_sum
constraint forall(j in 1..n) (
    sum(i in 1..n) (square[i, j]) = magic_sum
);

% Sum of the main diagonal must be equal to magic_sum
constraint sum(i in 1..n) (square[i, i]) = magic_sum;

% Sum of the anti-diagonal must be equal to magic_sum
constraint sum(i in 1..n) (square[i, n - i + 1]) = magic_sum;

% Solve the model
solve satisfy;

% Print the solution in JSON format
output [
    "{",
    "\"" ++ "square" ++ "\": [" ++ join([ "[" ++ join([show(square[i, j]) | j in 1..n], ", ") ++ "]" | i in 1..n], ", ") ++ "]",
    "}"
];
