% Include libraries if needed
include "globals.mzn";

% Input data
int: num_jobs = 3;
int: num_tasks_max = 3; % Maximum number of tasks in any job
int: num_machines = 3;

% jobs_data[job][task] = (machine, duration)
array[1..num_jobs, 1..num_tasks_max] of pair of int: jobs_data = 
    array2d(1..num_jobs, 1..num_tasks_max, [
        (0, 3), (1, 2), (2, 2),  % Job 0
        (0, 2), (2, 1), (1, 4),  % Job 1
        (1, 4), (2, 3), (-1, -1) % Job 2 (using -1 as a placeholder for non-existent tasks)
    ]);

% Decision Variables
% start_time[job][task] is the start time of task t in job j
array[1..num_jobs, 1..num_tasks_max] of var 0..100: start_time;
% makespan is the total time taken to complete all jobs
var 0..100: makespan;

% Constraints
% 1. Each task must start after the previous task of the same job is completed
constraint forall(j in 1..num_jobs) (
    forall(t in 2..num_tasks_max where jobs_data[j, t] != (-1, -1)) (
        start_time[j, t] >= start_time[j, t-1] + jobs_data[j, t-1].2
    )
);

% 2. No two tasks can be scheduled on the same machine at the same time
constraint forall(m in 0..num_machines-1) (
    forall(j1 in 1..num_jobs, t1 in 1..num_tasks_max where jobs_data[j1, t1] != (-1, -1)) (
        forall(j2 in j1+1..num_jobs, t2 in 1..num_tasks_max where jobs_data[j2, t2] != (-1, -1)) (
            jobs_data[j1, t1].1 == m -> 
                start_time[j1, t1] + jobs_data[j1, t1].2 <= start_time[j2, t2] 
                \/ start_time[j2, t2] + jobs_data[j2, t2].2 <= start_time[j1, t1]
        )
    )
);

% 3. Define makespan as the maximum end time of any task
constraint makespan = max(
    [start_time[j, t] + jobs_data[j, t].2 | j in 1..num_jobs, t in 1..num_tasks_max where jobs_data[j, t] != (-1, -1)]
);

% Solve the model to minimize makespan
solve minimize makespan;

% Print the solution in JSON format
output [
    "{",
    "\"" ++ "makespan" ++ "\": " ++ show(makespan),
    "}"
];
```

