% Constraint to ensure each step is a valid move from the previous step
predicate valid_move(array[1..3, 1..3] of int: prev, array[1..3, 1..3] of int: curr) =
    let {
        int: zero_x_prev;
        int: zero_y_prev;
        int: zero_x_curr;
        int: zero_y_curr;
        constraint find_zero(prev, zero_x_prev, zero_y_prev);
