constraint forall(j in 1..num_jobs) (
    start_time[j] + durations_data[j] <= makespan
);

% Precedence constraints
constraint forall(i in 1..18) (
    start_time[successors_link_data[i, 1]] + durations_data[successors_link_data[i, 1]] <= start_time[successors_link_data[i, 2]]
