constraint forall(i in 1..num_cities, j in 1..num_cities) (
    distance[i, j] = abs(locations[i, 1] - locations[j, 1]) + abs(locations[i, 2] - locations[j, 2])
);

% Decision Variables
array[1..num_cities] of var 1..num_cities: tour;
var int: travel_distance;

% Constraints
% All cities must be visited exactly once
constraint alldifferent(tour);

% Subtour elimination constraints
array[1..num_cities] of var 0..num_cities: s;
constraint s[1] = 1;
constraint forall(i in 2..num_cities) (
    s[i] >= 1 /\ s[i] <= num_cities
);
constraint forall(i in 2..num_cities) (
    s[i] - s[tour[i]] + num_cities * (1 - bool2int(tour[i] = i)) <= num_cities - 1
);

% Calculate the total travel distance
constraint travel_distance = sum(i in 1..num_cities) (
    distance[tour[i], tour[i mod num_cities + 1]]
);

% Solve the model to minimize the travel distance
solve minimize travel_distance;

% Print the solution in JSON format
output [
    "{",
    "\"" ++ "travel_distance" ++ "\": " ++ show(travel_distance),
    "}"
];
