include "globals.mzn";

% Input data
int: n_slots = 9;  % The amount of slots on a template
int: n_templates = 2;  % The amount of templates
int: n_var = 7;  % The amount of different variations
array[1..n_var] of int: demand = [250, 255, 260, 500, 500, 800, 1100];  % The demand per variation

% Decision Variables
% x[i, j] is the number of copies of variation i on template j
array[1..n_var, 1..n_templates] of var 0..max(demand): x;
% production[j] is the number of sheets produced for template j
array[1..n_templates] of var 0..sum(demand): production;

% Constraints
% Each template can only have a certain number of slots
constraint forall(j in 1..n_templates) (
    sum(i in 1..n_var) (x[i, j]) <= n_slots * production[j]
);

% Meet the demand for each variation
constraint forall(i in 1..n_var) (
    sum(j in 1..n_templates) (x[i, j]) == demand[i]
);

% Objective: Minimize the total number of sheets produced
solve minimize sum(j in 1..n_templates) (production[j]);

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "production" ++ "\": [" ++ join(",", [show(production[j]) | j in 1..n_templates]) ++ "]",
        "\"" ++ "layout" ++ "\": [" ++ join(",", [ "[" ++ join(",", [show(x[i, j]) | i in 1..n_var]) ++ "]" | j in 1..n_templates]) ++ "]"
    ]),
    "}"
];
