% Input data
int: n = 10;  % Length of the binary sequence

% Decision Variables
array[1..n] of var {-1, 1}: sequence;  % Binary sequence with values +1 or -1

% Constraints
% Calculate the autocorrelations for non-periodic boundary conditions
array[1..n-1] of var int: C;
constraint forall(k in 1..n-1) (
    C[k] = sum(i in 1..n-k) (sequence[i] * sequence[i+k])
);

% Objective: Minimize the sum of the squares of the autocorrelations
var int: E = sum(k in 1..n-1) (C[k] * C[k]);

% Solve the model to minimize the energy value
solve minimize E;

% Print the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "sequence" ++ "\": [" ++ join(",", [show(sequence[i]) | i in 1..n]) ++ "]",
        "\"" ++ "E" ++ "\": " ++ show(E)
    ]),
    "}"
];
