% Include libraries if needed
include "globals.mzn";

% Input data
int: n_weeks = 4;  % Number of weeks
int: n_groups = 3;  % Number of groups
int: group_size = 3;  % Size of each group
int: n_golfers = n_groups * group_size;  % Total number of golfers

% Decision Variables
array[1..n_weeks, 1..n_groups, 1..group_size] of var 1..n_golfers: assign;

% Constraints
% Each golfer appears exactly once per week
constraint forall(w in 1..n_weeks, g in 1..n_golfers) (
    sum(g2 in 1..n_groups, gs in 1..group_size) (bool2int(assign[w, g2, gs] = g)) = 1
);

% No golfer plays in the same group as any other golfer more than once
constraint forall(w1 in 1..n_weeks, w2 in w1+1..n_weeks, g1 in 1..n_groups, g2 in 1..n_groups) (
    sum(gs1 in 1..group_size, gs2 in 1..group_size) (
        bool2int(assign[w1, g1, gs1] = assign[w2, g2, gs2]) +
        bool2int(assign[w1, g1, gs1] = assign[w2, g2, gs2 + 1 mod group_size]) +
        bool2int(assign[w1, g1, gs1] = assign[w2, g2, gs2 + 2 mod group_size])
    ) <= 1
);

% All golfers in a group are distinct
constraint forall(w in 1..n_weeks, g in 1..n_groups) (
    all_different([assign[w, g, gs] | gs in 1..group_size])
);

solve satisfy;

% Print the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "assign" ++ "\": [" ++ join(",", [
            "[" ++ join(",", [
                "[" ++ join(",", [show(assign[w, g, gs]) | gs in 1..group_size]) ++ "]"
            | g in 1..n_groups]) ++ "]"
        | w in 1..n_weeks]) ++ "]"
    ]),
    "}"
];
