% Include libraries if needed
include "globals.mzn";

% Input data
int: n_teams = 9;
int: n_days = 18;
set of int: Teams = 1..n_teams;
set of int: Days = 1..n_days;

% Team names for reference
array[Teams] of string: team_names = ["Clem", "Duke", "FSU", "GT", "UMD", "UNC", "NCSt", "UVA", "Wake"];

% Mirroring scheme
array[1..9, 1..2] of int: mirroring = array2d(1..9, 1..2, [1, 8, 2, 9, 3, 12, 4, 13, 5, 14, 6, 15, 7, 16, 10, 17, 11, 18]);

% Rival pairs
array[1..4, 1..2] of int: rivals = array2d(1..4, 1..2, [2, 6, 1, 4, 5, 9, 4, 8]);

% Constrained matches
array[1..4, 1..2] of int: constrained_matches = array2d(1..4, 1..2, [9, 6, 9, 2, 4, 6, 4, 2]);

% Decision Variables
% match[i, j] = 1 if team i plays team j on day j, 0 otherwise
array[Teams, Days] of var 0..1: match;
% home[i, j] = 1 if team i plays at home on day j, 0 otherwise
array[Teams, Days] of var 0..1: home;
% away[i, j] = 1 if team i plays away on day j, 0 otherwise
array[Teams, Days] of var 0..1: away;
% bye[i, j] = 1 if team i has a bye on day j, 0 otherwise
array[Teams, Days] of var 0..1: bye;

% Constraints
% Each team plays each other exactly once at home and once away
constraint forall(i, j in Teams where i != j) (
    sum(k in Days) (match[i, k] /\ (home[i, k] \/ away[i, k])) = 1 /\
    sum(k in Days) (match[j, k] /\ (home[j, k] \/ away[j, k])) = 1
);

% Each team plays exactly one match, home, away, or bye per day
constraint forall(i in Teams, j in Days) (
    match[i, j] + home[i, j] + away[i, j] + bye[i, j] = 1
);

% Mirroring scheme
constraint forall(p in 1..9) (
    forall(i in Teams) (
        sum(j in mirroring[p, 1..2]) (match[i, j]) = 1
    )
);

% No two final aways
constraint forall(i in Teams) (
    away[i, n_days] + away[i, n_days - 1] <= 1
);

% Home/Away/Bye Pattern Constraints
constraint forall(i in Teams) (
    % No more than two away matches in a row
    forall(j in 1..(n_days - 2)) (
        away[i, j] + away[i, j + 1] + away[i, j + 2] <= 2
    ) /\
    % No more than two home matches in a row
    forall(j in 1..(n_days - 2)) (
        home[i, j] + home[i, j + 1] + home[i, j + 2] <= 2
    ) /\
    % No more than three away matches or byes in a row
    forall(j in 1..(n_days - 3)) (
        away[i, j] + away[i, j + 1] + away[i, j + 2] + away[i, j + 3] <= 3 /\
        bye[i, j] + bye[i, j + 1] + bye[i, j + 2] + bye[i, j + 3] <= 3
    ) /\
    % No more than four home matches or byes in a row
    forall(j in 1..(n_days - 4)) (
        home[i, j] + home[i, j + 1] + home[i, j + 2] + home[i, j + 3] + home[i, j + 4] <= 4 /\
        bye[i, j] + bye[i, j + 1] + bye[i, j + 2] + bye[i, j + 3] + bye[i, j + 4] <= 4
    )
);

% Weekend Pattern
constraint forall(i in Teams) (
    sum(j in 2..n_days by 2) (home[i, j]) = 4 /\
    sum(j in 2..n_days by 2) (away[i, j]) = 4 /\
    sum(j in 2..n_days by 2) (bye[i, j]) = 1
);

% First Weekends
constraint forall(i in Teams) (
    sum(j in 2..10 by 2) (home[i, j] + bye[i, j]) >= 2
);

% Rival Matches
constraint forall(p in 1..4) (
    match[rivals[p, 1], n_days] = 1 \/ match[rivals[p, 2], n_days] = 1
);
constraint match[6, 11] = 1; % UNC plays Duke in date 11
constraint match[1, 2] = 1; % Clem plays UNC in date 2

% Constrained Matches
constraint forall(p in 1..4) (
    sum(j in 11..n_days) (match[constrained_matches[p, 1], j] /\ match[constrained_matches[p, 2], j]) >= 1
);

% Opponent Sequence Constraints
constraint forall(i in Teams) (
    % No team plays in two consecutive dates away against UNC and Duke
    forall(j in 1..(n_days - 1)) (
        away[i, j] * match[6, j] * away[i, j + 1] * match[2, j + 1] = 0
    ) /\
    % No team plays in three consecutive dates against UNC, Duke and Wake (independent of home/away)
    forall(j in 1..(n_days - 2)) (
