        match[6, j] * match[2, j + 1] * match[9, j] + match[6, j] * match[2, j + 1] * match[9, j + 1] + match[6, j] * match[2, j + 1] * match[9, j + 2] +
        match[6, j] * match[2, j + 2] * match[9, j] + match[6, j] * match[2, j + 2] * match[9, j + 1] + match[6, j] * match[2, j + 2] * match[9, j + 2] +
        match[6, j + 1] * match[2, j + 1] * match[9, j] + match[6, j + 1] * match[2, j + 1] * match[9, j + 1] + match[6, j + 1] * match[2, j + 1] * match[9, j + 2] +
        match[6, j + 1] * match[2, j + 2] * match[9, j] + match[6, j + 1] * match[2, j + 2] * match[9, j + 1] + match[6, j + 1] * match[2, j + 2] * match[9, j + 2] +
        match[6, j + 2] * match[2, j + 2] * match[9, j] + match[6, j + 2] * match[2, j + 2] * match[9, j + 1] + match[6, j + 2] * match[2, j + 2] * match[9, j + 2] = 0
    )
);

% Other Constraints
constraint bye[2, 16] = 1; % Duke has a bye in date 16
constraint home[9, 17] = 0; % Wake does not play home in date 17
constraint bye[9, 1] = 1; % Wake has a bye in the first date
constraint away[1, n_days] = 0 /\ away[2, n_days] = 0 /\ away[4, n_days] = 0 /\ away[9, n_days] = 0; % Clem, Duke, UMD and Wake do not play away in the last date
constraint away[1, 1] = 0 /\ away[3, 1] = 0 /\ away[4, 1] = 0 /\ away[9, 1] = 0; % Clem, FSU, GT and Wake do not play away in the first date
constraint bye[3, n_days] = 0 /\ bye[5, n_days] = 0; % Neither FSU nor NCSt have a bye in the last date
constraint bye[6, 1] = 0; % UNC does not have a bye in the first date

% Solve the model
solve satisfy;

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "config" ++ "\": [" ++ join(",", [
            "[" ++ join(",", [
                "\"" ++ team_names[i] ++ "\"",
                "\"" ++ team_names[j] ++ "\"",
                if match[i, d] = 1 then if home[i, d] = 1 then "home" else "away" endif else "bye" endif
            ]) ++ "]"
            | i, j in Teams where i != j, d in Days, match[i, d] = 1
        ]) ++ "]",
        "\"" ++ "where" ++ "\": [" ++ join(",", [
            "[" ++ join(",", [
                "\"" ++ team_names[i] ++ "\"",
                if home[i, d] = 1 then "home" else if away[i, d] = 1 then "away" else "bye" endif endif
            ]) ++ "]"
            | i in Teams, d in Days
        ]) ++ "]"
    ]),
    "}"
];
