array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];  % Crew sizes of the boats

% Decision Variables
array[1..n_boats] of var 0..1: is_host;  % 1 if boat is a host, 0 otherwise
array[1..n_boats, 1..n_periods] of var 0..n_boats: visits;  % visits[b, p] is the host boat visited by boat b in period p

% Constraints
% Each boat must visit a host boat in each period
constraint forall(b in 1..n_boats, p in 1..n_periods) (
    is_host[visits[b, p]] = 1
);

% A boat cannot visit itself
constraint forall(b in 1..n_boats, p in 1..n_periods) (
    visits[b, p] != b
);

% A guest crew cannot meet more than once
constraint forall(b1 in 1..n_boats, b2 in b1+1..n_boats, p1 in 1..n_periods, p2 in p1+1..n_periods) (
    visits[b1, p1] != visits[b2, p2] \/ visits[b1, p2] != visits[b2, p1]
);

% Capacity constraint: total number of people on a host boat must not exceed its capacity
constraint forall(h in 1..n_boats, p in 1..n_periods) (
    sum(b in 1..n_boats) (bool2int(visits[b, p] = h) * crew_size[b]) + crew_size[h] <= capacity[h] * is_host[h]
);

% Minimize the number of host boats
solve minimize sum(h in 1..n_boats) (is_host[h]);

% Print the solution in JSON format
output [
    "{",
