% Include libraries if needed
include "globals.mzn";

% Input data
int: n = 13;  % Number of balls
int: c = 3;  % Number of boxes

% Decision Variables
array[1..n, 1..c] of var 0..1: M;  % M[i,j] is 1 if ball i is in box j, 0 otherwise

% Constraints
% Each ball must be in exactly one box
constraint forall(i in 1..n) (
    sum(j in 1..c) (M[i,j]) = 1
);

% For each triple (x, y, z) with x + y = z, not all can be in the same box
constraint forall(j in 1..c) (
    forall(x in 1..n, y in 1..n where x < y, z in 1..n where x + y = z) (
        M[x,j] + M[y,j] + M[z,j] <= 2
    )
);

solve satisfy;

% Output the assignment of balls to boxes as a list of n integers from 1 to 3
output [
    "{",
    "\"balls\": [" ++ join(",", [show(sum(j in 1..c) (j * M[i,j])) | i in 1..n]) ++ "]",
    "}"
];
```

