% Include libraries if needed
include "globals.mzn";

% Input data
int: k = 4;  % Number of sets
int: n = 4;  % Numbers from 1 to n

% Decision Variables
% position[i, j] is the position of the j-th occurrence of the number i in the sequence
array[1..n, 1..k] of var 1..(n*k): position;

% solution is the final sequence of numbers
array[1..(n*k)] of var 1..n: solution;

% Constraints
% All positions must be distinct
constraint all_different([position[i, j] | i in 1..n, j in 1..k]);

% Each number m must appear m numbers apart
constraint forall(i in 1..n, j in 1..(k-1)) (
    position[i, j+1] = position[i, j] + i
);

% The solution array must be consistent with the position array
constraint forall(p in 1..(n*k)) (
    exists(i in 1..n, j in 1..k) (
        position[i, j] = p -> solution[p] = i
    )
);

solve satisfy;

% Print the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "position" ++ "\": [" ++ join(",", [show(position[i, j]) | i in 1..n, j in 1..k]) ++ "]",
        "\"" ++ "solution" ++ "\": [" ++ join(",", [show(solution[p]) | p in 1..(n*k)]) ++ "]"
    ]),
    "}"
];
