    exists(i in 1..n, j in 1..k) (
        position[i, j] = p -> solution[p] = i
    )
);

solve satisfy;

% Print the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "position" ++ "\": [" ++ join(",", [show(position[i, j]) | i in 1..n, j in 1..k]) ++ "]",
        "\"" ++ "solution" ++ "\": [" ++ join(",", [show(solution[p]) | p in 1..(n*k)]) ++ "]"
    ]),
    "}"
];
