% Include libraries if needed
include "globals.mzn";

% Input data
int: n = 8;  % Number of words to find
int: length = 8;  % Length of each word
set of int: WORDS = 1..n;
set of int: POSITIONS = 1..length;
set of string: ALPHABET = {"A", "C", "G", "T"};
set of string: CG = {"C", "G"};

% Decision Variables
array[WORDS, POSITIONS] of var ALPHABET: words;

% Helper function to compute the Watson-Crick complement of a word
function array[POSITIONS] of string: wc_complement(array[POSITIONS] of string: word) =
    [if word[p] = "A" then "T" elseif word[p] = "T" then "A" elseif word[p] = "C" then "G" else "C" endif | p in POSITIONS];

% Helper function to compute the reverse of a word
function array[POSITIONS] of string: reverse(array[POSITIONS] of string: word) =
    [word[length - p + 1] | p in POSITIONS];

% Constraints
% Each word has exactly 4 symbols from {C, G}
constraint forall(w in WORDS) (
    sum(p in POSITIONS)(bool2int(words[w, p] in CG)) = 4
);

% Each pair of distinct words differ in at least 4 positions
constraint forall(w1, w2 in WORDS where w1 < w2) (
    sum(p in POSITIONS)(bool2int(words[w1, p] != words[w2, p])) >= 4
);

% Each pair of words (x, y) are such that x^R and y^C differ in at least 4 positions
constraint forall(w1, w2 in WORDS) (
    sum(p in POSITIONS)(bool2int(reverse(words[w1, POSITIONS]) [p] != wc_complement(words[w2, POSITIONS]) [p])) >= 4
);

solve maximize n;

% Print the solution in JSON format
output [
    "{",
    "\"words\": [" ++ join(",", [ "[" ++ join(",", [ "\"" ++ words[w, p] ++ "\"" | p in POSITIONS]) ++ "]" | w in WORDS]) ++ "]",
    "}"
];
