% Decision Variables
% x[i] = 1 if i is in set A, 0 if i is in set B
array[1..n] of var 0..1: x;

% Constraints
% A and B have the same cardinality
constraint sum(x) = n div 2;

% Sum of numbers in A = sum of numbers in B
constraint sum([i * x[i] | i in 1..n]) = sum([i * (1 - x[i]) | i in 1..n]);

% Sum of squares of numbers in A = sum of squares of numbers in B
constraint sum([i * i * x[i] | i in 1..n]) = sum([i * i * (1 - x[i]) | i in 1..n]);

% Solve the model
solve satisfy;

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "A" ++ "\": [" ++ join(",", [show(i) | i in 1..n where x[i] = 1]) ++ "]",
        "\"" ++ "B" ++ "\": [" ++ join(",", [show(i) | i in 1..n where x[i] = 0]) ++ "]"
    ]),
    "}"
];
