% Include libraries if needed
include "globals.mzn";

% Input data
set of int: WAREHOUSES = 1..4;
set of int: REGIONS = 1..3;
string: warehouse_s[WAREHOUSES] = ["New York", "Los Angeles", "Chicago", "Atlanta"];
int: fixed_costs[WAREHOUSES] = [400, 500, 300, 150];
int: max_shipping = 100;
int: demands[REGIONS] = [80, 70, 40];
int: shipping_costs[WAREHOUSES, REGIONS] = 
    array2d(WAREHOUSES, REGIONS, [
        20, 40, 50,  % New York to regions 1, 2, 3
        48, 15, 26,  % Los Angeles to regions 1, 2, 3
        26, 35, 18,  % Chicago to regions 1, 2, 3
        24, 50, 35   % Atlanta to regions 1, 2, 3
    ]);

% Decision Variables
var 0..1: open_warehouse[WAREHOUSES];
var 0..max_shipping: ships[WAREHOUSES, REGIONS];

% Constraints
% If the New York warehouse is opened, then the Los Angeles warehouse must also be opened.
constraint open_warehouse[1] <= open_warehouse[2];

% No more than three warehouses can be operational in any given week.
constraint sum(open_warehouse) <= 3;

% Either the Atlanta or the Los Angeles warehouse must be opened.
constraint open_warehouse[2] + open_warehouse[4] >= 1;

% Meet the demand for each region
constraint forall(r in REGIONS) (
    sum(w in WAREHOUSES) (ships[w, r]) = demands[r]
);

% Ensure that shipping does not exceed the capacity of open warehouses
constraint forall(w in WAREHOUSES, r in REGIONS) (
    ships[w, r] <= open_warehouse[w] * max_shipping
);

% Objective: Minimize total cost
var int: total_cost = 
    sum(w in WAREHOUSES) (open_warehouse[w] * fixed_costs[w]) +
    sum(w in WAREHOUSES, r in REGIONS) (ships[w, r] * shipping_costs[w, r]);

solve minimize total_cost;

% Print the solution in JSON format
output [
    "{",
    join(",", [
        "\"" ++ "total_cost" ++ "\": " ++ show(total_cost),
        "\"" ++ "open_warehouse" ++ "\": [" ++ join(",", [show(open_warehouse[w]) | w in WAREHOUSES]) ++ "]",
        "\"" ++ "ships" ++ "\": [" ++ join(",", [ "[" ++ join(",", [show(ships[w, r]) | r in REGIONS]) ++ "]" | w in WAREHOUSES]) ++ "]"
    ]),
    "}"
];
```

